package com.jh.gateway

import android.content.Context
import android.content.Intent
import android.net.Uri
import androidx.core.content.FileProvider
import org.json.JSONObject
import java.io.File
import java.net.HttpURLConnection
import java.net.URL

data class AvailableUpdate(val versionCode: Int, val versionName: String, val apkUrl: String)

/** Downloads the latest release APK and opens Android's safe package installer. */
class UpdateManager(private val context: Context) {
    // Release assets are generated by the tag workflow. Keep this URL free of tokens.
    private val latestReleaseApi = "https://api.github.com/repos/jhanik54/jh-getway/releases/latest"

    fun check(onResult: (Result<AvailableUpdate?>) -> Unit) {
        Thread {
            val result = runCatching {
                val connection = URL(latestReleaseApi).openConnection() as HttpURLConnection
                connection.connectTimeout = 10_000
                connection.readTimeout = 10_000
                connection.setRequestProperty("Accept", "application/vnd.github+json")
                val json = connection.inputStream.bufferedReader().use { it.readText() }
                connection.disconnect()
                val release = JSONObject(json)
                val asset = release.getJSONArray("assets").let { assets ->
                    (0 until assets.length()).asSequence().map { assets.getJSONObject(it) }.firstOrNull { it.getString("name").endsWith(".apk") }
                } ?: return@runCatching null
                val versionName = release.getString("tag_name").removePrefix("v")
                val versionCode = versionName.substringBefore('.').toIntOrNull() ?: 0
                if (versionCode > BuildConfig.VERSION_CODE) AvailableUpdate(versionCode, versionName, asset.getString("browser_download_url")) else null
            }
            onResult(result)
        }.start()
    }

    fun downloadAndInstall(update: AvailableUpdate, onResult: (Result<Unit>) -> Unit) {
        Thread {
            val result = runCatching {
                val folder = File(context.cacheDir, "updates").apply { mkdirs() }
                val apk = File(folder, "jh-getway-${update.versionName}.apk")
                (URL(update.apkUrl).openConnection() as HttpURLConnection).apply {
                    connectTimeout = 15_000
                    readTimeout = 120_000
                    inputStream.use { input -> apk.outputStream().use { output -> input.copyTo(output) } }
                    disconnect()
                }
                val uri = FileProvider.getUriForFile(context, "com.jh.gateway.fileprovider", apk)
                context.startActivity(Intent(Intent.ACTION_VIEW).apply { setDataAndType(uri, "application/vnd.android.package-archive"); addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_GRANT_READ_URI_PERMISSION) })
            }
            onResult(result)
        }.start()
    }
}
